function validateProject(p){
 if(!p||p.version!==1||typeof p.code!=='string'||p.code.length>100000||typeof p.name!=='string'||p.name.length>100||!Array.isArray(p.parts)||p.parts.length>100||!Array.isArray(p.wires)||p.wires.length>300)throw Error('Файл проекта повреждён или имеет неподдерживаемый формат.');
 const ids=new Set();for(const part of p.parts){if(!byId[part.type]?.ready||typeof part.id!=='string'||!/^[\w-]{1,80}$/.test(part.id)||ids.has(part.id)||!Number.isFinite(part.x)||!Number.isFinite(part.y)||Math.abs(part.x)>5000||Math.abs(part.y)>5000)throw Error('В проекте есть неподдерживаемый компонент.');ids.add(part.id);part.attrs??={};}
 for(const w of p.wires)if(typeof w.from!=='string'||typeof w.to!=='string'||!ids.has(w.from.split(':')[0])||!ids.has(w.to.split(':')[0])||!/^#[\da-f]{6}$/i.test(w.color))throw Error('В проекте есть некорректное соединение.');
}
