function toast(title,detail='',kind='success'){
 const el=document.createElement('div');el.className=`toast ${kind}`;el.innerHTML=`<span class="toast-icon">${icon(kind==='error'?'circle-alert':kind==='info'?'info':'check')}</span><div><strong>${esc(title)}</strong>${detail?`<p>${esc(detail)}</p>`:''}</div><button class="icon-btn" aria-label="Закрыть">${icon('x')}</button>`;$('#toasts').append(el);el.querySelector('button').onclick=()=>el.remove();refreshIcons();setTimeout(()=>el.remove(),kind==='error'?9000:4200);
}
function audio(){if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext;}
function chime(){if(!sound)return;try{const ctx=audio();[523.25,659.25,783.99].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+i*.085;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.055,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+.24);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+.25);});}catch{}}
function setBuzz(id,f){if(!sound||!running||paused||f<20||f>20000){if(buzzers[id]){buzzers[id].stop();delete buzzers[id];}return;}try{const ctx=audio();if(!buzzers[id]){const o=ctx.createOscillator(),g=ctx.createGain();g.gain.value=.018;o.type='square';o.connect(g).connect(ctx.destination);o.start();buzzers[id]=o;}buzzers[id].frequency.value=f;}catch{}}
function silent(){for(const id in buzzers)setBuzz(id,0);}
