function fitCatalog(){$$('.component-art').forEach(async holder=>{const el=holder.firstElementChild;if(!el?.tagName.startsWith('WOKWI-'))return;await el.updateComplete;el.style.transform='none';const w=el.offsetWidth,h=el.offsetHeight;if(!w||!h)return;el.style.transform=`scale(${Math.min(82/w,48/h,1.2)})`;el.setAttribute('aria-hidden','true');el.setAttribute('inert','');});}
const deviceScale=p=>p.type==='uno'?1.08:p.type==='led'||p.type==='rgb'?1.8:p.type==='resistor'?1.2:1;
