function input(id,value){inputs[id]=value;worker?.postMessage({type:'input',id,value});}
function point(endpoint){const[id,name]=endpoint.split(':'),part=project.parts.find(p=>p.id===id),el=elements.get(id),pin=el?.pinInfo?.find(p=>p.name===name);if(!part||!pin)return null;return{x:part.x+pin.x*deviceScale(part),y:part.y+pin.y*deviceScale(part),partId:id};}
function routingBoxes(){return project.parts.map(p=>{const el=elements.get(p.id)?.closest('.part');return{id:p.id,x:p.x,y:p.y,w:parseFloat(el?.style.width)||40,h:parseFloat(el?.style.height)||40};});}
function pathBetween(a,b,boxes=routingBoxes()){return pointsToPath(routeWire(a,b,boxes));}
function drawWires(){
 const boxes=routingBoxes();$('#wires').innerHTML=project.wires.map(w=>{const a=point(w.from),b=point(w.to);if(!a||!b)return'';const path=pathBetween(a,b,boxes),fallback=`M ${a.x} ${a.y} L ${b.x} ${b.y}`;return`<g data-wire="${esc(w.id)}" class="${path?'':'route-blocked'}"><title>Нажмите, чтобы изменить провод</title><path class="wire-hit" d="${path||fallback}"/><path class="wire-line" stroke="${w.color}" d="${path||fallback}"/><circle cx="${a.x}" cy="${a.y}" r="3" fill="${w.color}"/><circle cx="${b.x}" cy="${b.y}" r="3" fill="${w.color}"/></g>`;}).join('')+'<path id="draft-wire"/>';if(wireStart&&draftCursor)renderDraft(draftCursor);
}
