 const p=project.parts.find(p=>p.id===selected);panel.innerHTML=`<div><strong>${esc(byId[p.type].name)}</strong><small>${esc(p.id)}${p.type==='resistor'?` · ${esc(p.attrs.value||220)} Ω`:''}</small></div>${p.type==='led'?`<input type="color" id="led-color" value="${/^#[\da-f]{6}$/i.test(p.attrs.color)?p.attrs.color:'#ff4444'}" aria-label="Цвет светодиода">`:''}${p.type==='resistor'?`<label class="resistance"><input id="resistance" type="number" min="1" max="10000000" value="${Number(p.attrs.value)||220}" aria-label="Сопротивление">Ω</label>`:''}<span class="inspector-actions">${btn('move','move-hint','Перемещение стрелками')}${btn('trash-2','delete','Удалить компонент')}${btn('x','deselect','Закрыть свойства')}</span>`;refreshIcons();$('#led-color')?.addEventListener('input',e=>{p.attrs.color=e.target.value;elements.get(p.id).color=e.target.value;saveSoon();});$('#resistance')?.addEventListener('change',e=>{if(running)return;checkpoint();p.attrs.value=String(Math.max(1,Math.min(10000000,Number(e.target.value)||220)));elements.get(p.id).value=p.attrs.value;saveSoon();});
