function selectPart(id){selectParts(id?[id]:[]);}
function editAllowed(){if(running||compiling){toast('Сначала остановите симуляцию','После остановки можно изменить схему.','info');return false;}return true;}
function addPart(type){if(!editAllowed())return;const p=byId[type];if(!p.ready){toast('Эта модель в разработке',p.name+' есть в каталоге, но ещё не моделируется.','info');return;}if(type==='uno'&&project.parts.some(p=>p.type==='uno'))return toast('Uno уже на схеме','В этой версии поддерживается одна плата.','info');checkpoint();const rect=$('#canvas').getBoundingClientRect();const id=type+'-'+uid();project.parts.push({id,type,x:Math.max(30,(rect.width*.6-offset.x)/zoom),y:Math.max(130,(rect.height*.55-offset.y)/zoom),attrs:type==='led'?{color:'red'}:type==='resistor'?{value:'220'}:{}});selected=id;selectedIds=new Set([id]);renderParts();saveSoon();$('.palette').classList.remove('open');}
function connect(endpoint){if(!editAllowed())return;if(!wireStart){selectPart(null);wireStart=endpoint;draftCursor=point(endpoint);$$('.pin').find(p=>p.dataset.pin===endpoint)?.classList.add('pending');$('#world').classList.add('drawing-wire');wireHint();return;}if(wireStart!==endpoint&&!project.wires.some(w=>(w.from===wireStart&&w.to===endpoint)||(w.to===wireStart&&w.from===endpoint))){checkpoint();project.wires.push({id:uid(),from:wireStart,to:endpoint,color:wireColor});saveSoon();}cancelWire();drawWires();refreshMeta();}
function cancelWire(){wireStart=null;draftCursor=null;$$('.pin.pending').forEach(p=>p.classList.remove('pending'));$('#world').classList.remove('drawing-wire');$('#draft-wire')?.setAttribute('d','');wireHint();}
$('#canvas').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.pin')){e.preventDefault();e.stopPropagation();connect(e.target.dataset.pin);}});

let drag=null;
function marqueeSelection(rect){return $$('.part').filter(part=>rectsIntersect(rect,part.getBoundingClientRect())).map(part=>part.dataset.id);}
function paintSelectionBox(rect){const canvasRect=$('#canvas').getBoundingClientRect(),box=$('#selection-box');Object.assign(box.style,{left:rect.left-canvasRect.left+'px',top:rect.top-canvasRect.top+'px',width:rect.width+'px',height:rect.height+'px'});box.hidden=false;}
function finishDrag(){if(!drag)return;$('#selection-box').hidden=true;if(drag.moved&&!drag.pan&&!drag.select)saveSoon();drag=null;}
$('#canvas').addEventListener('pointerdown',e=>{
 if(e.target.closest('#inspector,.canvas-bottom'))return;
 if((e.ctrlKey||e.metaKey)&&e.button===0&&mode==='select'&&!wireStart){
  e.preventDefault();drag={select:true,startX:e.clientX,startY:e.clientY,moved:false};paintSelectionBox(normalizeRect(e.clientX,e.clientY,e.clientX,e.clientY));$('#canvas').setPointerCapture(e.pointerId);return;
 }
 const pin=e.target.closest('[data-pin]');if(pin){e.preventDefault();connect(pin.dataset.pin);return;}
 if(wireStart){e.preventDefault();return;}
 const w=e.target.closest('[data-wire]');if(w){if(editAllowed()){const id=w.dataset.wire;openDialog('Соединение',`<p class="dialog-text">${esc(project.wires.find(w=>w.id===id).from)} → ${esc(project.wires.find(w=>w.id===id).to)}</p><button class="button danger" id="remove-wire">${icon('trash-2')}Удалить провод</button>`);$('#remove-wire').onclick=()=>{checkpoint();project.wires=project.wires.filter(w=>w.id!==id);drawWires();refreshMeta();saveSoon();closeDialog();};}return;}
 const wrapper=e.target.closest('.part');
 if(wrapper){
  const id=wrapper.dataset.id;if(!selectedIds.has(id))selectPart(id);if(running)return;
  checkpoint();const chosen=project.parts.filter(p=>selectedIds.has(p.id));drag={group:true,startX:e.clientX,startY:e.clientY,moved:false,positions:chosen.map(p=>({id:p.id,x:p.x,y:p.y}))};wrapper.setPointerCapture(e.pointerId);e.preventDefault();
 }else if(!e.target.closest('button')){
  selectPart(null);drag={pan:true,startX:e.clientX,startY:e.clientY,x:offset.x,y:offset.y};$('#canvas').setPointerCapture(e.pointerId);
 }
});
$('#canvas').addEventListener('pointermove',e=>{
 if(drag){
  if(drag.select){const rect=normalizeRect(drag.startX,drag.startY,e.clientX,e.clientY);drag.moved=rect.width>3||rect.height>3;paintSelectionBox(rect);selectParts(drag.moved?marqueeSelection(rect):[]);}
  else if(drag.pan){offset={x:drag.x+e.clientX-drag.startX,y:drag.y+e.clientY-drag.startY};setTransform();}
  else if(drag.group){
   const rawX=(e.clientX-drag.startX)/zoom,rawY=(e.clientY-drag.startY)/zoom;drag.moved=drag.moved||Math.abs(rawX)>1||Math.abs(rawY)>1;
   const delta=clampGroupDelta(drag.positions,rawX,rawY);
   for(const start of drag.positions){const p=project.parts.find(p=>p.id===start.id);p.x=start.x+delta.x;p.y=start.y+delta.y;const el=$$('.part').find(el=>el.dataset.id===p.id);el.style.left=p.x+'px';el.style.top=p.y+'px';}
   updateGroupFrame();drawWires();
  }
 }
 if(wireStart){const target=e.target.closest('[data-pin]');renderDraft(target?point(target.dataset.pin):worldPoint(e));}
});
$('#canvas').addEventListener('pointerup',finishDrag);
$('#canvas').addEventListener('pointercancel',finishDrag);
$('#canvas').addEventListener('wheel',e=>{e.preventDefault();const rect=$('#canvas').getBoundingClientRect(),old=zoom;zoom=Math.max(.3,Math.min(2.5,zoom*(e.deltaY>0?.92:1.08)));offset.x=e.clientX-rect.left-(e.clientX-rect.left-offset.x)*zoom/old;offset.y=e.clientY-rect.top-(e.clientY-rect.top-offset.y)*zoom/old;setTransform();},{passive:false});

let logCount=0,serialLines=0;
function appendLog(text,kind='info'){const row=document.createElement('div');row.className=`log-line ${kind}`;row.textContent=text;$('#build-output').append(row);$('#build-output').scrollTop=$('#build-output').scrollHeight;$('#log-count').textContent=++logCount;while($('#build-output').children.length>200)$('#build-output').firstChild.remove();}
function appendSerial(text){if(!serialLines)$('#serial-output').innerHTML='';serialLines++;const row=document.createElement('div');row.className='serial-line';const time=document.createElement('span');time.className='serial-time';time.textContent=seconds.toFixed(3).padStart(7,'0');const content=document.createElement('span');content.textContent=text;row.append(time,content);$('#serial-output').append(row);while($('#serial-output').children.length>400)$('#serial-output').firstChild.remove();$('#serial-output').scrollTop=$('#serial-output').scrollHeight;}
function consolePanel(panel){activePanel=panel;$('#serial-output').hidden=panel!=='serial';$('#build-output').hidden=panel!=='logs';$('[data-action="serial-panel"]').classList.toggle('active',panel==='serial');$('[data-action="logs-panel"]').classList.toggle('active',panel==='logs');}
async function run(){
 if(running){stop();return;}if(compiling)return;cancelWire();dismissError();
 if(containsProfanity(project.code)){appendLog('Запуск остановлен: в коде обнаружена ненормативная лексика.','error');showProfanityWarning();return;}
 const generation=++runGeneration,sourceCode=project.code;
 try{
  const warnings=validateCircuit(project);for(const warning of warnings)appendLog('△ '+warning,'warning');
  compiling=true;$('#run').innerHTML=`${icon('loader-circle','spin')}<span>Собираем…</span>`;$('#run').disabled=true;$('#canvas-status').textContent='Компиляция скетча…';refreshIcons();if(sound)audio();
  let result;if(hexFile){result={hex:hexFile,stdout:'Загружена прошивка Intel HEX. Содержимое редактора не компилировалось.'};}
  else if(compiler){const response=await fetch('/api/compile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:project.code}),signal:AbortSignal.timeout(65000)});result=await response.json();if(!response.ok||!result.hex)throw Error(result.error||'Компилятор не вернул прошивку.');}
  else{const sample=examples.find(ex=>ex.code===project.code);if(!sample){throw Error('Веб-версия запускает готовые примеры и файлы .hex. Для сборки изменённого C++ откройте локальный SIMduino lab на компьютере с Arduino CLI. Ваш код сохранён.');}result=(await firmware)[sample.id];if(!result?.hex)throw Error('Не удалось загрузить готовую прошивку.');}
  if(generation!==runGeneration)return;if(project.code!==sourceCode)throw Error('Код изменился во время сборки. Нажмите «Запустить» ещё раз.');
  loadHex(result.hex);appendLog(hexFile?'Запуск загруженной прошивки.':compiler?'Сборка завершена · Arduino Uno':'Загружена готовая прошивка примера.','success');if(result.stdout)appendLog(result.stdout.trim());
  seconds=0;serialLines=0;$('#serial-output').innerHTML='';worker=new Worker('/simulator.js',{type:'module'});worker.onmessage=({data})=>{
   if(data.type==='ready'){running=true;paused=false;setRunUI();chime();launchFireworks();showSuccessReaction();toast('Схема ожила','Arduino Uno выполняет вашу прошивку.');appendLog('Эмуляция ATmega328P запущена · 16 MHz','success');}
   if(data.type==='frame'){seconds=data.seconds;updateAmbient(data.outputs,project.parts);for(const [id,out]of Object.entries(data.outputs)){const el=elements.get(id);if(!el)continue;if('brightness'in out){el.value=out.brightness>.005;el.brightness=out.brightness;el.style.filter=out.brightness>.05?`drop-shadow(0 0 ${10*out.brightness}px ${project.parts.find(p=>p.id===id).attrs.color||'red'})`:'';}if(out.rgb){[el.ledRed,el.ledGreen,el.ledBlue]=out.rgb;}if('angle'in out)el.angle=out.angle;if('frequency'in out)setBuzz(id,out.frequency);}
    const uno=elements.get(project.parts.find(p=>p.type==='uno').id);if(uno){uno.ledPower=true;uno.led13=data.pins[13]>.1;}$('#simulation-time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${(seconds%60).toFixed(3).padStart(6,'0')}`;
   }if(data.type==='serial')appendSerial(data.line);if(data.type==='error'){stop();showError(data.message);}
  };worker.onerror=e=>{stop();showError(e.message||'Ошибка эмулятора.');};worker.postMessage({type:'start',hex:result.hex,project:structuredClone(project),inputs});
 }catch(e){showError(e.message);$('#canvas-status').textContent='Исправьте ошибку';}
 finally{if(generation===runGeneration){compiling=false;$('#run').disabled=false;if(!running)setRunUI();}}
}
function setRunUI(){
 $('#run').innerHTML=running?`${icon('square')}<span>Остановить</span><kbd>⌘ ↵</kbd>`:`${icon('play')}<span>Запустить</span><kbd>⌘ ↵</kbd>`;$('#run').classList.toggle('running',running);$('#run-dot').classList.toggle('live',running&&!paused);$('#canvas-status').textContent=running?(paused?'На паузе':'Симуляция работает'):'Готово к запуску';$('#world').classList.toggle('simulating',running);$('#bottom-status').textContent=running?'Эмуляция в браузере':'Локальное сохранение';$('.canvas-caption').classList.toggle('dim',running);refreshIcons();
}
function stop(){runGeneration++;worker?.terminate();worker=null;running=false;paused=false;compiling=false;$('#run').disabled=false;clearAmbient();silent();elements.forEach(el=>{if('value'in el&&el.tagName==='WOKWI-LED'){el.value=false;el.brightness=0;el.style.filter='';}if('ledRed'in el){el.ledRed=0;el.ledGreen=0;el.ledBlue=0;}if('ledPower'in el)el.ledPower=false;if('led13'in el)el.led13=false;});setRunUI();}
function showError(message){appendLog(message,'error');consolePanel('logs');showCompileError(message);showFailureReaction();toast('Не удалось запустить',message.split('\n').find(s=>s.includes('error:'))||message.slice(0,200),'error');}
function openDialog(title,content,wide=false){const d=$('#modal');d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-header"><h2>${esc(title)}</h2>${btn('x','close','Закрыть')}</div><div class="dialog-body">${content}</div>`;if(!d.open)d.showModal();refreshIcons();}
