$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function rememberProject(){try{const stored=JSON.parse(localStorage.getItem('volt.projects')||'[]'),i=stored.findIndex(x=>x.name===project.name),entry={...structuredClone(project),updated:Date.now()};if(i>=0)stored[i]=entry;else stored.unshift(entry);localStorage.setItem('volt.projects',JSON.stringify(stored.slice(0,30)));}catch{}}
